package eu.europa.esig.dss.eaa.mdoc.revocation.validation.identifierlist;

import eu.europa.esig.dss.eaa.mdoc.validation.MdocIssuerSignedAttestationDocumentAnalyzer;
import eu.europa.esig.dss.eaa.revocation.validation.AttestationRevocationValidator;
import eu.europa.esig.dss.eaa.revocation.validation.identifierlist.ISO180135AttestationIdentifierListValidator;
import eu.europa.esig.dss.enumerations.AttestationStatus;
import eu.europa.esig.dss.model.InMemoryDocument;
import eu.europa.esig.dss.spi.eaa.Attestation;
import eu.europa.esig.dss.spi.eaa.AttestationPresentation;
import eu.europa.esig.dss.spi.eaa.AttestationRevocationToken;
import eu.europa.esig.dss.utils.Utils;
import org.junit.jupiter.api.Test;

import java.util.List;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class ISO180135AttestationIdentifierListValidatorTest {

    @Test
    void test() {
        String mdocB64 = "";
        String revocationListB64 = "";
        byte[] revocationList = Utils.fromBase64(revocationListB64);

        AttestationPresentation attestationPresentation = new MdocIssuerSignedAttestationDocumentAnalyzer(new InMemoryDocument(Utils.fromBase64(mdocB64))).getAttestationPresentation();
        List<Attestation> electronicAttestationsOfAttributes = attestationPresentation.getElectronicAttestationsOfAttributes();

        Attestation attestation = electronicAttestationsOfAttributes.get(0);

        AttestationRevocationValidator validator = new ISO180135AttestationIdentifierListValidator();
        assertTrue(validator.isSupported(attestation));

        List<String> uris = validator.getUris(attestation);
        assertEquals(1, uris.size());

        AttestationRevocationToken attestationRevocationToken = validator.validate(attestation, revocationList);
        assertNotNull(attestationRevocationToken);
        assertEquals(AttestationStatus.VALID, attestationRevocationToken.getStatus());
        assertArrayEquals(revocationList, attestationRevocationToken.getEncoded());
        assertNotNull(attestationRevocationToken.getCreationDate());
        assertNotNull(attestationRevocationToken.getExpirationDate());
        assertEquals(uris.get(0), attestationRevocationToken.getSubject());
    }

    @Test
    void statusListTest() {
        String mdocB64 = "";
        String revocationListB64 = "";
        byte[] revocationList = Utils.fromBase64(revocationListB64);

        AttestationPresentation attestationPresentation = new MdocIssuerSignedAttestationDocumentAnalyzer(new InMemoryDocument(Utils.fromBase64(mdocB64))).getAttestationPresentation();
        List<Attestation> electronicAttestationsOfAttributes = attestationPresentation.getElectronicAttestationsOfAttributes();

        Attestation attestation = electronicAttestationsOfAttributes.get(0);

        AttestationRevocationValidator validator = new ISO180135AttestationIdentifierListValidator();
        assertFalse(validator.isSupported(attestation));

        Exception exception = assertThrows(UnsupportedOperationException.class, () -> validator.getUris(attestation));
        assertEquals("The provided EAA token does not contain 'identifier_list' or not supported!", exception.getMessage());

        exception = assertThrows(UnsupportedOperationException.class, () -> validator.validate(attestation, revocationList));
        assertEquals("The provided EAA token does not contain 'identifier_list' or not supported!", exception.getMessage());
    }

}
